<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=html_escape($room->rmTitle)?></title><link rel="stylesheet" href="<?=base_url('assets/css/website.css')?>"><style>.room-detail{max-width:1180px;margin:45px auto;padding:20px;display:grid;grid-template-columns:1.2fr 1fr;gap:38px}.gallery{position:relative}.gallery #mainRoomImage{width:100%;height:440px;object-fit:cover;border-radius:12px}.gallery-control{position:absolute;top:42%;border:0;border-radius:50%;width:42px;height:42px;background:rgba(0,0,0,.55);color:#fff;font-size:24px;cursor:pointer}.gallery-prev{left:12px}.gallery-next{right:12px}.thumbs{display:flex;gap:8px;overflow:auto;margin-top:10px}.thumbs img{width:90px;height:70px;object-fit:cover;cursor:pointer;border-radius:6px}.room-info{padding:12px 0}.room-info .book-button{display:inline-block;padding:13px 22px;background:#182b28;color:white;text-decoration:none;border-radius:6px;margin-top:15px}@media(max-width:760px){.room-detail{grid-template-columns:1fr}.gallery img{height:300px}}</style></head><body><?php $this->load->view('website/partials/navigation'); ?><main class="room-detail"><section class="gallery"><?php if($images):?><img id="mainRoomImage" src="<?=base_url($images[0]->rmiPath)?>" alt="Room image"><button class="gallery-control gallery-prev" type="button" aria-label="Previous image">‹</button><button class="gallery-control gallery-next" type="button" aria-label="Next image">›</button><div class="thumbs"><?php foreach($images as $image):?><img src="<?=base_url($image->rmiPath)?>" alt="Room image" onclick="document.getElementById('mainRoomImage').src=this.src"><?php endforeach;?></div><?php else:?><div style="height:440px;background:#eee;border-radius:12px"></div><?php endif;?></section><section class="room-info"><p class="eyebrow">ROOM DETAILS</p><h1><?=html_escape($room->rmTitle)?></h1><h2>₱<?=number_format((float)$room->rmPrice,2)?> <small>/ night</small></h2><p><?=nl2br(html_escape($room->rmDesc))?></p><p><?=nl2br(html_escape($room->rmInfo))?></p><p><strong>Capacity:</strong> <?=html_escape($room->rmCapacity)?> guests</p><a class="book-button" href="<?=base_url('booknow/'.$room->rmID)?>">Book Now</a></section></main><?php $this->load->view('website/partials/footer'); ?><script>
(function(){var images=<?=json_encode(array_map(function($im){return base_url($im->rmiPath);},$images))?>;if(!images.length)return;var i=0,main=document.getElementById('mainRoomImage');function show(n){i=(n+images.length)%images.length;main.src=images[i];}document.querySelector('.gallery-prev').addEventListener('click',function(){show(i-1)});document.querySelector('.gallery-next').addEventListener('click',function(){show(i+1)});document.querySelectorAll('.thumbs img').forEach(function(el,n){el.addEventListener('click',function(){show(n)})});})();
</script></body></html>